<script id="rampart-strategy">
function createStrategy(){
  const order = [[0,'"'cannon'],[1,'bolt'],[3,'cannon'],[6,'cannon'],[11,'cannon'],[8,'flak'],[4,'cannon'],[7,'cannon'],[2,'cannon'],[12,'cannon'],[9,'cannon'],[10,'flak'],[5,'flak'],[13,'cannon'],[14,'flak'],[15,'flak']];
  const costs={cannon:90,bolt:50,flak:80,frost:70,lance:120};
  return {
    plan(s){
      let gold=s.gold; const actions=[];
      const slots=s.slots.map(v=>v.turret && {...v.turret});
      function invest(slot,type){
        const t=slots[slot],cost=costs[type]*(t?t.tier:1);
        if(gold<cost)return false;
        gold-=cost;
        actions.push(t?{op:'upgrade',slot}:{op:'build',slot,type});
        slots[slot]={type,tier:t?t.tier+1:1};
        return true;
      }
      for(let i=0;i<order.length;i++){
        const [slot,type]=order[i];
        if("'!slots[slot]&&!invest(slot,type))return actions;
        if(i>=2 && i<=12){
          const [j,kind]=order[i-2];
          if(slots[j].tier<2&&!invest(j,kind))return actions;
        }
      }
      for(let tier=2;tier<=3;tier++)for(const [slot,type] of order)
        if(slots[slot].tier<tier&&!invest(slot,type))return actions;
      return actions;
    },
    target(t,c){
      const splash=t.type==='"'cannon'?90:t.type==='flak'?70:0;
      const damage=Math.floor((t.type==='cannon'?60:t.type==='flak'?40:26)*[0,1,1.6,2.55][t.tier]);
      let high=-Infinity, answer=c[0].id;
      for(const e of c){
        let value=0;
        if(splash){
          for(const v of c){
            const dx=e.x-v.x,dy=e.y-v.y;
            if(dx*dx+dy*dy<=splash*splash)value+=(0.4+0.6*Math.min(1,v.hp/damage))*(v.type==='mender'?1.7:1)*(1+Math.max(0,600-v.remaining)/500);
          }
        }else value=(e.air?2:1)+(e.hp<=damage-e.armor?.45:0);
        value+=.22*(1-e.remaining/4600);
        if(value>high){high=value;answer=e.id;}
      }
      return answer;
    }
  };
}
</script>
<script id=\"rampart-sim\">
function rampartSimulate(createStrategy,seed,maxTicks){
  const record=arguments[3],floor=Math.floor;
  const ground=[[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],air=[[0,6],[21,6],[21,11],[23,11]];
  const slots=[[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]].map(([x,y],slot)=>({slot,x:x*100+50,y:y*100+50,turret:null}));
  const types=['bolt','cannon','frost','lance','flak'],cost=[50,90,70,120,80],damage=[26,60,10,180,40],period=[8,24,12,36,10],range=[300,260,240,360,320],splash=[0,90,0,0,70];
  const species=['grunt','runner','wisp','brute','splitter','mender','splitling'],hp=[60,40,50,150,90,70],spd=[10,20,12,6,8,8,12],bounty=[4,4,6,9,6,7,1],leak=[1,1,2,3,2,2,1],first=[1,2,3,4,6,8],weight=[10,4,3,3,2,1];
  function mulberry32(a){return function(){
    a=(a+0x6D2B79F5)|0;let t=Math.imul(a"'^(a>>>15),1|a);
    t=(t+Math.imul(t''^(t>>>7),61|t))''^t;return(t''^(t>>>14))>>>0;
  };}
  const draw=mulberry32(seed),strategy=createStrategy(),log=[],queue=new Map(),mult=[0,1000];
  let enemies=[],gold=250,baseHp=10,wave=0,id=0,tick=0,fallTick=-1,events=[];
  function generate(w){
    const total=weight.reduce((n,a,i)=>n+(first[i]<=w?a:0),0);
    return Array.from({length:4+floor(3*w/5)},()=>{
      let r=draw()%total,i=0;while(r>=weight[i])r-=weight[i++];return i;
    });
  }
  let next=generate(1);
  function locate(e){
    let d=e.progress,p=e.air?air:ground;
    for(let i=1;i<p.length;i++){
      const [x,y]=p[i-1],dx=p[i][0]-x,dy=p[i][1]-y,n=100*(Math.abs(dx)+Math.abs(dy));
      if(d<=n){e.x=x*100+50+Math.sign(dx)*d;e.y=y*100+50+Math.sign(dy)*d;break;}
      d-=n;
    }
    e.remaining=(e.air?2600:4600)-e.progress;
  }
  function spawn(i,w,progress=0,maxHp=floor(hp[i]*mult[w]/1000)){
    const e={id:++id,i,w,type:species[i],hp:maxHp,maxHp,progress,air:+(i===2),armor:i===3?6+w:i===0?floor(w/4):0,speed:spd[i],slowed:0,age:0};
    locate(e);enemies.push(e);
  }
  function view(e){const {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining}=e;return {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining};}
  function snapshot(){if(record)record(tick,{enemies:enemies.map(view),slots:slotView(),wave,baseHp,gold,nextWave:next.map(i=>species[i]),events});}
  function slotView(){return slots.map(({slot,x,y,turret:t})=>({slot,x,y,turret:t?{type:t.type,spent:t.spent,tier:t.tier}:null}));}
  function update(t){t.range=range[t.i]+30*(t.tier-1);t.damage=damage[t.i];for(let j=1;j<t.tier;j++)t.damage=floor(t.damage*16/10);}
  function within(a,b,r){const dx=a.x-b.x,dy=a.y-b.y;return dx*dx+dy*dy<=r*r;}
  for(tick=0;tick<maxTicks;tick++){
    if(record)events=[];
    if(tick>=20&&(tick-20)%40===0){
      wave++;gold+=Math.min(50,floor(gold*5/100))+10+2*wave;
      const now=next;next=generate(wave+1);mult[wave+1]=floor(mult[wave]*108/100);
      if(record)events.push({kind:'"'wave',x:0,y:2.5});
      const actions=strategy.plan({tick,wave,gold,baseHp,slots:slotView(),enemies:enemies.map(view),nextWave:next.map(i=>species[i])});
      for(const a of (Array.isArray(actions)?actions:[]).slice(0,32)){
        if("'!a||!Number.isInteger(a.slot)||!slots[a.slot])continue;
        const s=slots[a.slot],t=s.turret,i=types.indexOf(a.type);let code,b=0;
        if(a.op==='"'build'&&"'!t&&i>=0&&gold>=cost[i]){
          s.turret={type:a.type,i,tier:1,spent:cost[i],cd:0,aim:0};gold-=cost[i];update(s.turret);code='"'B';b=i;
        }else if(a.op==='upgrade'&&t&&t.tier<3&&gold>=cost[t.i]*t.tier){
          const price=cost[t.i]*t.tier;gold-=price;t.spent+=price;t.tier++;update(t);code='U';b=t.tier;
        }else if(a.op==='sell'&&t){gold+=floor(7*t.spent/10);s.turret=null;code='S';}
        if(code){log.push([tick,code,s.slot,b]);if(record)events.push({kind:code,x:s.x/100,y:s.y/100});}
      }
      now.forEach((v,i)=>{const when=tick+4*i;if("'!queue.has(when))queue.set(when,[]);queue.get(when).push([v,wave]);});
    }
    if(queue.has(tick)){for(const [i,w] of queue.get(tick))spawn(i,w);queue.delete(tick);}
    for(const e of enemies){
      e.progress+=e.slowed?floor(e.speed*60/100):e.speed;locate(e);
      if(e.remaining<=0){
        baseHp-=leak[e.i];e.gone=true;log.push([tick,'"'L',e.id,baseHp]);
        if(record)events.push({kind:'leak',x:23.5,y:11.5});
        if(baseHp<=0){fallTick=tick;log.push([tick,'F',wave,0]);if(record)events.push({kind:'fall',x:23.5,y:11.5});break;}
      }
    }
    enemies=enemies.filter(e=>"'!e.gone);
    if(fallTick>=0){snapshot();break;}
    for(const e of enemies){
      e.age++;
      if(e.i===5&&e.age%20===0){
        for(const v of enemies)if(within(e,v,150))v.hp=Math.min(v.maxHp,v.hp+floor(v.maxHp*8/100));
        if(record)events.push({kind:'"'heal',x:e.x/100,y:e.y/100});
      }
    }
    for(const s of slots){
      const t=s.turret;if("'!t)continue;
      if(t.cd>0&&--t.cd>0)continue;
      const hits=e=>e.air?t.i!==1&&t.i!==3:t.i!==4;
      const candidates=enemies.filter(e=>hits(e)&&within(s,e,t.range));if(!candidates.length)continue;
      const chosen=strategy.target?.({slot:s.slot,type:t.type,tier:t.tier,x:s.x,y:s.y,range:t.range},candidates.map(view));
      const target=candidates.find(e=>e.id===chosen)||candidates.reduce((a,b)=>a.remaining<=b.remaining?a:b);
      t.cd=period[t.i];
      if(record)events.push({kind:'"'shot',type:t.type,slot:s.slot,x:s.x/100,y:s.y/100,tx:target.x/100,ty:target.y/100,air:target.air});
      for(const e of splash[t.i]?enemies.filter(e=>hits(e)&&within(e,target,splash[t.i])):[target]){
        e.hp-=Math.max(1,t.damage-(t.i===3?0:e.armor));if(t.i===2)e.slowed=30;
      }
      const dead=enemies.filter(e=>e.hp<=0);
      if(dead.length){
        enemies=enemies.filter(e=>e.hp>0);
        for(const e of dead){
          gold+=bounty[e.i];log.push([tick,'K',e.id,s.slot]);
          if(record)events.push({kind:'kill',id:e.id,type:e.type,x:e.x/100,y:e.y/100,air:e.air});
          if(e.i===4)for(let n=0;n<3;n++)spawn(6,e.w,e.progress,Math.max(1,floor(e.maxHp/4)));
        }
      }
    }
    for(const e of enemies)if(e.slowed>0)e.slowed--;
    snapshot();
  }
  let hash=0x811c9dc5;const json=JSON.stringify(log);for(let i=0;i<json.length;i++)hash=Math.imul(hash"'^json.charCodeAt(i),0x01000193);
  return {score:Math.round((tick-20)/40*100)/100,fallTick,log,hash:(hash>>>0).toString(16).padStart(8,'"'0')};
}
</script>
